Here a simple DNS Test Server 

``` java

import java.util.List;
import java.util.Map;

import io.netty.bootstrap.Bootstrap;
import io.netty.buffer.ByteBuf;
import io.netty.channel.ChannelFuture;
import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.ChannelInboundHandlerAdapter;
import io.netty.channel.ChannelInitializer;
import io.netty.channel.EventLoopGroup;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.DatagramChannel;
import io.netty.channel.socket.nio.NioDatagramChannel;
import io.netty.handler.codec.dns.DatagramDnsQuery;
import io.netty.handler.codec.dns.DatagramDnsQueryDecoder;
import io.netty.handler.codec.dns.DatagramDnsResponse;
import io.netty.handler.codec.dns.DatagramDnsResponseEncoder;
import io.netty.handler.codec.dns.DefaultDnsRawRecord;
import io.netty.handler.codec.dns.DnsRecord;
import io.netty.handler.codec.dns.DnsRecordType;
import io.netty.handler.codec.dns.DnsSection;

public class LocalDNSTestServer implements Runnable {

    private final Map<String, List<DNSTestClient.Record>> dnsEntries;
    private volatile boolean isStarted = false;
    private final int port;
    private ChannelFuture f;

    public LocalDNSTestServer(final int port, final Map<String, List<DNSTestClient.Record>> map) {

        this.dnsEntries = map;
        this.port = port;
    }

    public void startServer() throws InterruptedException {
        final EventLoopGroup bossGroup = new NioEventLoopGroup();
        try {
            final Bootstrap b = new Bootstrap();
            b.group(bossGroup).channel(NioDatagramChannel.class).handler(new ChannelInitializer<DatagramChannel>() {
                @Override
                public void initChannel(final DatagramChannel ch) throws Exception {
                    ch.pipeline().addLast(new DatagramDnsResponseEncoder());
                    ch.pipeline().addLast(new DatagramDnsQueryDecoder());
                    ch.pipeline().addLast(new LocalDNSSDHandler());
                }
            });
            this.f = b.bind(this.port).sync();
            this.isStarted = true;
            this.f.channel().closeFuture().sync();
        } finally {
            bossGroup.shutdownGracefully();
        }
    }

    public void stopServer() {
        this.f.channel().close();
    }

    public class LocalDNSSDHandler extends ChannelInboundHandlerAdapter {
        @Override
        public void channelRead(final ChannelHandlerContext ctx, final Object msg) {
            final DatagramDnsQuery query = (DatagramDnsQuery) msg;
            DatagramDnsResponse defaultDnsResponse = null;
            try {
                final DnsRecord recordAt = query.recordAt(DnsSection.QUESTION);
                final List<DNSTestClient.Record> list = LocalDNSTestServer.this.getDnsEntries().get(recordAt.name());
                defaultDnsResponse = new DatagramDnsResponse(query.recipient(), query.sender(), query.id());
                defaultDnsResponse.addRecord(DnsSection.QUESTION, recordAt);
                for (final DNSTestClient.Record record : list) {
                    final ByteBuf buffer = ctx.alloc().buffer();
                    defaultDnsResponse.addRecord(DnsSection.ANSWER, new DefaultDnsRawRecord(record.getName().toString(), DnsRecordType.PTR, Long.MAX_VALUE, buffer));
                }
            } catch (final Exception e) {
            }
            ctx.writeAndFlush(defaultDnsResponse);
        }

        @Override
        public void exceptionCaught(final ChannelHandlerContext ctx, final Throwable cause) {
            cause.printStackTrace();
            ctx.close();
        }
    }

    @Override
    public void run() {
        try {
            this.startServer();
        } catch (final InterruptedException e) {
            e.printStackTrace();
        }
    }

    public boolean isStarted() {
        return this.isStarted;
    }

    public Map<String, List<DNSTestClient.Record>> getDnsEntries() {
        return this.dnsEntries;
    }

}
```

And here a simple DNS Client:

``` java

import static org.junit.Assert.assertTrue;

import java.net.InetSocketAddress;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

import org.junit.BeforeClass;
import org.junit.Test;

import io.netty.channel.AddressedEnvelope;
import io.netty.channel.ChannelFactory;
import io.netty.channel.EventLoop;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.DatagramChannel;
import io.netty.channel.socket.nio.NioDatagramChannel;
import io.netty.handler.codec.dns.DefaultDnsQuestion;
import io.netty.handler.codec.dns.DnsRecord;
import io.netty.handler.codec.dns.DnsRecordType;
import io.netty.handler.codec.dns.DnsResponse;
import io.netty.handler.codec.dns.DnsSection;
import io.netty.resolver.dns.DnsNameResolver;
import io.netty.resolver.dns.DnsNameResolverBuilder;
import io.netty.resolver.dns.DnsServerAddressStream;
import io.netty.resolver.dns.DnsServerAddresses;
import io.netty.util.concurrent.Future;
import io.netty.util.concurrent.GenericFutureListener;

public class DNSTestClient {
    private static Thread localDnsTestServerThread;
    private static LocalDNSTestServer localDnsTestServer;
    private static Map<String, List<Record>> expectedMap;
    public static final int LOCAL_DNS_SERVER_PORT = 9595;
    public static final String TEST_BASE_RECORD_NAME = "_fd-srv._tcp.vsdm.telematik-test.";

    public static Map<String, List<Record>> getTestEntries() {
        final Map<String, List<Record>> map = new HashMap<>();
        map.put(TEST_BASE_RECORD_NAME, Arrays.asList(() -> "_Record0._tcp.vsdm.telematik-test.", () -> "_Record1._tcp.vsdm.telematik-test.", () -> "_Record2._tcp.vsdm.telematik-test."));
        return map;
    }

    public static interface Record {
        String getName();
    }

    @BeforeClass
    public static void initTest() throws Exception {
        localDnsTestServer = new LocalDNSTestServer(LOCAL_DNS_SERVER_PORT, expectedMap = getTestEntries());
        localDnsTestServerThread = new Thread(localDnsTestServer);
        localDnsTestServerThread.start();
        int waitCount = 0;
        final int sleepTimeInSeconds = 5;
        final int maxWaits = 42;
        while (!localDnsTestServer.isStarted()) {
            try {
                Thread.sleep(TimeUnit.SECONDS.toMillis(sleepTimeInSeconds));
                if (++waitCount > maxWaits) {
                    throw new InstantiationException("Could not setup LocalDnsTestServer in Time!");
                }
            } catch (final InterruptedException e) {
            }
        }
    }

    @Test
    public void testNewApi() throws Exception {
        final NioEventLoopGroup nioEventLoopGroup = new NioEventLoopGroup();
        final EventLoop next = nioEventLoopGroup.next();
        final DnsNameResolverBuilder dnsNameResolverBuilder = new DnsNameResolverBuilder(next).channelFactory(new ChannelFactory<DatagramChannel>() {
            @Override
            public DatagramChannel newChannel() {
                return new NioDatagramChannel();
            }
        }).nameServerAddresses(new DnsServerAddresses() {
            @Override
            public DnsServerAddressStream stream() {
                return new DnsServerAddressStream() {
                    @Override
                    public InetSocketAddress next() {
                        return new InetSocketAddress("127.0.0.1", LOCAL_DNS_SERVER_PORT);
                    }
                };
            }
        });
        final DnsNameResolver build = dnsNameResolverBuilder.build();
        final DefaultDnsQuestion defaultDnsQuestion = new DefaultDnsQuestion(TEST_BASE_RECORD_NAME, DnsRecordType.PTR);
        build.query(defaultDnsQuestion).addListener(new GenericFutureListener<Future<? super AddressedEnvelope<DnsResponse, InetSocketAddress>>>() {
            @Override
            public void operationComplete(final Future<? super AddressedEnvelope<DnsResponse, InetSocketAddress>> future) throws Exception {
                final AddressedEnvelope<DnsResponse, InetSocketAddress> answer = (AddressedEnvelope<DnsResponse, InetSocketAddress>) future.get();
                final DnsResponse content = answer.content();
                final int count = content.count(DnsSection.ANSWER);
                assertTrue("ANSWER Section has wrong size.", count == expectedMap.get(TEST_BASE_RECORD_NAME).size());
                for (int i = 0; i < count; i++) {
                    final DnsRecord recordAt = content.recordAt(DnsSection.ANSWER, i);
                    System.out.println(recordAt);
                }

            }
        }).await();
        // needed to wait for operationComplete to run.
        Thread.sleep(Long.MAX_VALUE);
    }
}

```

The test `testNewApi` will fail, since only 1 record will be returned, instead of 3
